#!/usr/bin/env python3
"""
Maktab Platformasi - Loyihani yaratuvchi skript

Foydalanish:
  1. Bu faylni nusxa oling va kompyuteringizga saqlang
  2. Terminalda ishga tushiring: python make_project.py
  3. school_app papkasi yaratiladi
  4. school_app papkasiga kiring: cd school_app
  5. Flask ornating: pip install flask
  6. Ishga tushiring: python run.py
  7. Brauzerda oching: http://127.0.0.1:5000
  8. Login: admin / Parol: admin123
"""

import os
import base64

PROJECT = "school_app"

# === FILE CONTENTS (base64 encoded) ===
FILES = {
    'app.py': '',
    'static/css/style.css': '',
    'templates/base.html': '',
    'templates/login.html': '',
    'templates/teacher/dashboard.html': '',
    'templates/teacher/students.html': '',
    'templates/teacher/create_student.html': '',
    'templates/teacher/schedule.html': '',
    'templates/teacher/attendance.html': '',
    'templates/teacher/my_attendance.html': '',
    'templates/teacher/comments.html': '',
    'templates/teacher/questions.html': '',
    'templates/teacher/results.html': '',
    'templates/teacher/support.html': '',
    'templates/student/dashboard.html': '',
    'templates/student/test.html': '',
    'templates/student/quiz.html': '',
    'templates/student/quiz_result.html': '',
    'templates/student/schedule_view.html': '',
    'templates/student/attendance.html': '',
    'templates/student/comments.html': '',
    'templates/student/support.html': '',
    'school_system_data.json': '',
    'custom_questions.json': 'e30=',
    'requirements.txt': 'Rmxhc2s9PTMuMC4wCmd1bmljb3JuPT0yMS4yLjAK',
    'Procfile': 'd2ViOiBndW5pY29ybiBhcHA6YXBwIC0tYmluZCAwLjAuMC4wOiRQT1JUIC0td29ya2VycyAyCg==',
    'runtime.txt': 'My4xMS4wCg==',
    '.gitignore': 'X19weWNhY2hlX18vCioucHljCioucHlvCi5lbnYKdmVudi8KLnZlbnYvCiouZGIK',
    'run.py': '',
    'run_windows.bat': '',
    'run_linux.sh': '',
    'static/manifest.json': '',
    'static/sw.js': '',
    'static/icons/icon-192.png': '',
    'static/icons/icon-512.png': '',
}


def create_project():
    """Create all project files from encoded content"""
    print("Maktab Platformasi loyihasi yaratilmoqda...")
    print()
    os.makedirs(PROJECT, exist_ok=True)

    for rel_path, encoded_content in FILES.items():
        full_path = os.path.join(PROJECT, rel_path)
        dir_name = os.path.dirname(full_path)
        if dir_name:
            os.makedirs(dir_name, exist_ok=True)

        decoded = base64.b64decode(encoded_content)

        if rel_path.endswith(".png"):
            with open(full_path, "wb") as f:
                f.write(decoded)
        else:
            with open(full_path, "w", encoding="utf-8") as f:
                f.write(decoded.decode("utf-8"))

        print(f"  {rel_path}")

    print()
    print("=" * 50)
    print("Loyiha muvaffaqiyatli yaratildi!")
    print()
    print("Keyingi qadamlar:")
    print("  1. cd school_app")
    print("  2. pip install flask")
    print("  3. python run.py")
    print("  4. Brauzerda oching: http://127.0.0.1:5000")
    print()
    print("Kirish malumotlari:")
    print("  Login: admin")
    print("  Parol: admin123")
    print("=" * 50)


if __name__ == "__main__":
    create_project()

